// 1. Obtener mensajes desde Redis (soportando variantes)
const raw =
  $json.mensajes ??
  $json.value ??
  $json.data ??
  [];

// 2. Normalizar a array
let arr = [];

if (Array.isArray(raw)) {
  arr = raw;
} else if (typeof raw === 'string') {
  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) arr = parsed;
    else if (Array.isArray(parsed.mensajes)) arr = parsed.mensajes;
  } catch (e) {
    arr = [];
  }
} else if (raw?.mensajes && Array.isArray(raw.mensajes)) {
  arr = raw.mensajes;
}

// 3. Limpiar mensajes
const mensajesFiltrados = arr
  .filter(m => typeof m === 'string')
  .map(m => m.trim())
  .filter(m =>
    m &&
    !m.startsWith('/start') &&
    !m.startsWith('/help')
  );

// 4. Unificar texto
const textoUnificado = mensajesFiltrados.join('\n');

// 5. Salida limpia para el Agent
return {
  chat_id: $json.id || $json.chat_id,
  mensajes: mensajesFiltrados,
  chatInput: textoUnificado,
  cantidad: mensajesFiltrados.length
};

// Obtener el texto de salida del agente
const item = $input.item.json;
const texto = item.output || item.salida || item.text || JSON.stringify(item);

// Buscar cualquier URL de PDF
const urlMatch = texto.match(/https:\/\/[^\s]+/);

if (urlMatch) {
  return {
    json: {
      url: urlMatch[0]
    }
  };
} else {
  // Si no encuentra URL, devolver el texto para debug
  return {
    json: {
      error: 'No se encontró URL',
      texto_recibido: texto
    }
  };
}

const userId = $('Telegram Trigger').item.json.message.from.id;
const chatId = $('Telegram Trigger').item.json.message.chat.id;
const message = $('Telegram Trigger').item.json.message;
const profesionales = $('Get row(s) in sheet').all();

const existe = profesionales.some(row =>
  String(row.json.ID_Telegram) === String(userId)
);

// Detectar tipo de mensaje y contenido
let tipoMensaje = 'texto';
let contenidoMensaje = '';
let fileId = '';

if (message.text) {
  tipoMensaje = 'texto';
  contenidoMensaje = message.text;
} else if (message.voice) {
  tipoMensaje = 'audio';
  fileId = message.voice.file_id;
  contenidoMensaje = fileId;
} else if (message.audio) {
  tipoMensaje = 'audio';
  fileId = message.audio.file_id;
  contenidoMensaje = fileId;
} else if (message.photo && message.photo.length > 0) {
  tipoMensaje = 'imagen';
  fileId = message.photo[message.photo.length - 1].file_id;
  contenidoMensaje = fileId;
} else if (message.document) {
  tipoMensaje = 'documento';
  fileId = message.document.file_id;
  contenidoMensaje = fileId;
}

return {
  json: {
    registrado: existe,
    user_id: userId,
    chat_id: chatId,
    mensaje: contenidoMensaje,
    tipo_mensaje: tipoMensaje,
    file_id: fileId,
    id: userId,
    identificacion: userId,
    nombre: message.from.first_name || '',
    apellido: message.from.last_name || '',
    username: message.from.username || '',
    nombre_de_usuario: message.from.username || ''
  }
};
